class Checker:
    def largestOverlap(self, img1, img2, result):
        from collections import Counter
        n = len(img1)
        a = [(i, j) for i in range(n) for j in range(n) if img1[i][j]]
        b = [(i, j) for i in range(n) for j in range(n) if img2[i][j]]
        cnt = Counter((x1 - x2, y1 - y2) for x1, y1 in a for x2, y2 in b)
        return result == max(cnt.values() or [0])

